import numpy as np
from rdkit import Chem
import matplotlib.pyplot as plt
import sys
p=sys.argv[1]
lines=open(p).read().splitlines();syms=[l.split()[0] for l in lines[2:]];r=np.array([[float(x) for x in l.split()[1:4]] for l in lines[2:]])
m=Chem.MolFromMolFile('ligand.mol',removeHs=False)
fig=plt.figure(figsize=(10,8)); ax=fig.add_subplot(projection='3d')
colors={'C':'gray','H':'white','N':'blue','Zr':'purple','Cl':'green'}
for i,(s,v) in enumerate(zip(syms,r)):
 ax.scatter(*v,color=colors[s],s=40 if s=='H' else 100,edgecolors='gray');
 if s in ['N','Zr','Cl']:ax.text(*v,f'{s}{i}')
for b in m.GetBonds():
 a,c=b.GetBeginAtomIdx(),b.GetEndAtomIdx();ax.plot(*r[[a,c]].T,color='gray',linewidth=1.5)
for a in [2,18,73,74,75]:ax.plot(*r[[a,72]].T,color='purple',linewidth=2)
ax.set_box_aspect(np.ptp(r,axis=0));ax.view_init(elev=25,azim=-75)
plt.tight_layout();plt.savefig('geometry.png',dpi=140)
